import java.time.Instant;
import java.util.List;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import com.example.starter.calibration.model.Measurement;

/**
 * SUSPECT 标记持久化。标记只增不改；解除仅写入清除信息，保留可追溯历史。
 */
@Repository
public class SuspectMarkingRepository {

    private final JdbcTemplate jdbc;

    public SuspectMarkingRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 将区间内全部已放行结果原子标记为该 FAIL 核查引入的 SUSPECT（须在事务内调用）。
     * 返回被标记的测量记录数。
     */
    public int markReleasedInRange(long checkId, String instrumentId,
                                   Instant from, Instant to, Instant markedAt) {
        throw new UnsupportedOperationException();
    }

    /** 该测量是否仍存在未解除的 SUSPECT 标记。 */
    public boolean hasActiveMarking(long measurementId) {
        throw new UnsupportedOperationException();
    }

    /** 查询某 FAIL 核查标记的全部测量记录（按测量 ID 升序）。 */
    public List<Measurement> findMeasurementsByCheckId(long checkId) {
        throw new UnsupportedOperationException();
    }

    /** 查询某测量的全部 SUSPECT 标记历史（含已解除，按标记 ID 升序）。 */
    public List<com.example.starter.calibration.model.SuspectMarking> findByMeasurementId(long measurementId) {
        throw new UnsupportedOperationException();
    }

    /**
     * 解除：清除这批 FAIL 核查引入、且测量不再被其他未解除区间覆盖的 SUSPECT 标记。
     * 证书撤销导致的不可用不受影响（本操作不触碰证书与放行历史）。
