    /** 隔离区间历史：可按仪器、是否已解除过滤。 */
    @Transactional(readOnly = true)
    public List<IsolationIntervalResponse> intervals(String instrumentId, Boolean resolved) {
        String instrument = normalizeInstrument(instrumentId);
