    @Test
    void pendingResultInsideRangeRejectedWithBlockingCheckKey() throws Exception {
        createCert("INS-B");
        submit("B-1", "INS-B", "2026-03-01T00:00:00Z", "alice");
        check("REQ-BF", "CK-BLOCK", "INS-B", "2026-04-01T00:00:00Z", "9", "1", "0.1")
