    @Test
    void laterPassResolvesIsolationButNotRevokedCertOrOtherFailCoverage() throws Exception {
        long certId = createCert("INS-V");
        submit("V-1", "INS-V", "2026-03-01T00:00:00Z", "alice");
        submit("V-2", "INS-V", "2026-03-02T00:00:00Z", "bob");
        submit("V-3", "INS-V", "2026-03-03T00:00:00Z", "bob");
        release("V-1", "V-2", "V-3");

        // FAIL1：04-01，区间从最早测量起，覆盖 V-1/V-2/V-3
        check("REQ-VF1", "CK-FAIL-1", "INS-V", "2026-04-01T00:00:00Z", "9", "1", "0.1")
                .andExpect(status().isCreated());
        // 撤销 V-1 的证书：解除隔离也不得恢复其可用性
        mvc.perform(post("/api/certificates/{id}/revoke", certId)).andExpect(status().isOk());

        // 更晚 PASS（05-01）解除 FAIL1
        check("REQ-VP", "CK-PASS-LATE", "INS-V", "2026-05-01T00:00:00Z", "1", "1", "0.1")
