        mvc.perform(get("/api/measurements/{key}", "V-1"))
                .andExpect(jsonPath("$.suspect").value(false))
                .andExpect(jsonPath("$.usable").value(false));

        // 重叠 FAIL：FAIL2(06-01) 后 FAIL3(07-01)，PASS(08-01) 同时解除；
        // 再构造 FAIL4(09-01) 与 PASS(08-15 不可能晚于09)... 改为顺序验证仍被覆盖不恢复
        submit("V-4", "INS-V", "2026-06-15T00:00:00Z", "bob");
