        check("REQ-VF3", "CK-FAIL-3", "INS-V", "2026-07-15T00:00:00Z", "9", "1", "0.1")
                .andExpect(status().isCreated());
        // PASS 08-01 解除 FAIL2、FAIL3：V-4 恢复
        check("REQ-VP2", "CK-PASS-2", "INS-V", "2026-08-01T00:00:00Z", "1", "1", "0.1")
                .andExpect(status().isCreated());
        mvc.perform(get("/api/measurements/{key}", "V-4"))
                .andExpect(jsonPath("$.suspect").value(false))
                .andExpect(jsonPath("$.usable").value(true));

